module temp_shutdown_controller (
    input wire clk,
    input wire rst_n,
    input wire [6:0] temperature,
    output reg shutdown
);
    parameter THRESHOLD = 7'd100;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shutdown <= 1'b0;
        end else begin
            if (temperature > THRESHOLD) begin
                shutdown <= 1'b1;
            end else begin
                shutdown <= 1'b0;
            end
        end
    end
endmodule

