module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);
    reg [3:0] bit_count;
    reg [10:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit
    reg [15:0] baud_count; // Adjustable baud rate counter

    parameter BAUD_RATE = 16'd104; // Example baud rate count value

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1'b1; // Idle state for UART is high
            busy <= 0;
            bit_count <= 0;
            baud_count <= 0;
        end else if (start && !busy) begin
            busy <= 1;
            shift_reg <= {1'b1, data_in, 1'b0}; // Start bit + data + stop bit
            bit_count <= 0;
            baud_count <= 0;
        end else if (busy) begin
            if (baud_count < BAUD_RATE) begin
                baud_count <= baud_count + 1;
            end else begin
                baud_count <= 0;
                tx <= shift_reg[bit_count]; // Shift out current bit
                if (bit_count < 10) begin
                    bit_count <= bit_count + 1;
                end else begin
                    busy <= 0; // Transmission complete
                    tx <= 1'b1; // Return to idle state
                end
            end
        end
    end
endmodule

