module simple_des(
    input wire clk,
    input wire reset,
    input wire [63:0] plaintext,
    input wire [63:0] key,
    output reg [63:0] ciphertext
);
    reg [63:0] round_key[1:0];
    reg [63:0] intermediate;

    // LFSR for key generation
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            round_key[0] <= key;
            round_key[1] <= {key[62:0], key[63]}; // Simple shift
        end else begin
            intermediate <= plaintext ^ round_key[0]; // Simple XOR operation for encryption
            ciphertext <= intermediate ^ round_key[1]; // Final encryption step
        end
    end
endmodule

