module LIFO_stack (
    input wire clk,
    input wire rst_n,
    input wire push,
    input wire pop,
    input wire [7:0] data_in,
    output reg [7:0] data_out,
    output reg empty,
    output reg full
);
    reg [7:0] stack [0:7];
    reg [2:0] top;

    initial begin
        top = 0;
        empty = 1;
        full = 0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            top <= 0;
            empty <= 1;
            full <= 0;
        end else begin
            if (push && !full) begin
                stack[top] <= data_in;
                top <= top + 1;
                empty <= 0;
                if (top + 1 == 8) full <= 1;
            end
            if (pop && !empty) begin
                top <= top - 1;
                data_out <= stack[top];
                full <= 0;
                if (top - 1 == 0) empty <= 1;
            end
        end
    end
endmodule

