    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        reset = 1;
        command = 0;
        repeat(2) @(posedge clk);
        reset = 0;
        @(posedge clk);
    end
        endtask
    task testcase001;

    begin
        test_num = 1;
        reset_dut();
        $display("Testcase %0d: Checking initial state after reset...", test_num);

        #1;


        check_outputs(1'b0);
    end
        endtask

    task testcase002;

    begin
        test_num = 2;
        reset_dut();
        $display("Testcase %0d: Checking normal command processing to completion...", test_num);

        command = 1;
        @(posedge clk);
        command = 0;



        fork : wait_for_done
            begin
                wait(done == 1'b1);
                disable wait_for_done;
            end
            begin
                repeat(100) @(posedge clk);
                $display("Timeout waiting for done signal");
                disable wait_for_done;
            end
        join


        #1;



        check_outputs(1'b1);
    end
        endtask

    task testcase003;

    begin
        test_num = 3;
        reset_dut();
        $display("Testcase %0d: Checking reset during PROCESSING state...", test_num);

        command = 1;
        @(posedge clk);
        command = 0;


        repeat(2) @(posedge clk);


        reset = 1;
        @(posedge clk);
        reset = 0;
        @(posedge clk);


