    end
        endtask

    task testcase005;

    begin
        test_num = 5;
        reset_dut();
        $display("Testcase %0d: Checking command signal held high...", test_num);

        command = 1;

        repeat(5) @(posedge clk);


        fork : wait_for_done_long
            begin
                wait(done == 1'b1);
                disable wait_for_done_long;
            end
            begin
                repeat(100) @(posedge clk);
                disable wait_for_done_long;
            end
        join

        #1;


        check_outputs(1'b1);
        command = 0;
        @(posedge clk);
    end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

