module fft_4point (  
    input wire clk,  
    input wire rst,  
    input wire [15:0] x0,  
    input wire [15:0] x1,  
    input wire [15:0] x2,  
    input wire [15:0] x3,  
    output reg [15:0] y0,  
    output reg [15:0] y1,  
    output reg [15:0] y2,  
    output reg [15:0] y3  
);  

    reg [15:0] stage_1 [0:3];  
    reg [15:0] stage_2 [0:3];  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            y0 <= 0;  
            y1 <= 0;  
            y2 <= 0;  
            y3 <= 0;  
        end else begin  
            // Stage 1: Compute the butterfly operations  
            stage_1[0] <= x0 + x1;  
            stage_1[1] <= x0 - x1;  
            stage_1[2] <= x2 + x3;  
            stage_1[3] <= x2 - x3;  

            // Stage 2: Final butterfly operations to get the FFT output  
            y0 <= stage_1[0] + stage_1[2];  
            y1 <= stage_1[1] + (stage_1[3] >>> 1);  
            y2 <= stage_1[0] - stage_1[2];  
            y3 <= stage_1[1] - (stage_1[3] >>> 1);  
        end  
    end  
endmodule

