module CSPRNG (  
    input clk,  
    input reset,  
    input [4:0] seed,  
    output reg [4:0] random_number  
);  
    reg [4:0] lfsr;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            lfsr <= seed;  
        end else begin  
            // Shift left and apply feedback  
            lfsr <= {lfsr[3:0], lfsr[4] ^ lfsr[1] ^ lfsr[0]};  
        end  
    end  

    always @(posedge clk) begin  
        random_number <= lfsr;  
    end  
endmodule

