module shift_register_16bit(  
    input clk,  
    input reset,  
    input shift_en,  
    input [15:0] data_in,  
    output reg [15:0] data_out  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset)  
            data_out <= 16'b0;  
        else if (shift_en)  
            data_out <= {data_out[14:0], data_in[0]};  
    end  
endmodule

