module stack_lifo (
    input clk,
    input rst,
    input push,
    input pop,
    input [7:0] data_in,
    output reg [7:0] data_out,
    output reg full,
    output reg empty
);
    reg [7:0] stack [0:7]; // Stack of depth 8
    reg [2:0] top; // Pointer to the top of the stack

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            top <= 3'b000;
            empty <= 1'b1;
            full <= 1'b0;
        end else begin
            if (push && !full) begin
                stack[top] <= data_in;
                top <= top + 1;
                empty <= 1'b0;
                if (top == 3'b111) full <= 1'b1;
            end else if (pop && !empty) begin
                top <= top - 1;
                data_out <= stack[top];
                full <= 1'b0;
                if (top == 3'b000) empty <= 1'b1;
            end
        end
    end
endmodule

