module uart_transmitter (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire tx_en,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000; // Example clock frequency
    localparam BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] bit_index;
    reg [$clog2(BIT_PERIOD)-1:0] clock_divider;
    reg sending;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx <= 1; // idle state
            busy <= 0;
            bit_index <= 0;
            clock_divider <= 0;
            sending <= 0;
        end else begin
            if (tx_en && !busy) begin
                busy <= 1;
                sending <= 1;
                tx <= 0; // start bit
                bit_index <= 0;
                clock_divider <= 0;
            end

            if (sending) begin
                clock_divider <= clock_divider + 1;
                if (clock_divider == BIT_PERIOD - 1) begin
                    clock_divider <= 0;
                    if (bit_index < 8) begin
                        tx <= data_in[bit_index]; // send data bits
                        bit_index <= bit_index + 1;
                    end else if (bit_index == 8) begin
                        tx <= 1; // stop bit
                        bit_index <= bit_index + 1;
                    end else begin
                        busy <= 0;
                        sending <= 0; // transmission finished
                    end
                end
            end
        end
    end
endmodule

module WatchdogTimer (
    input clk,
    input reset,
    input enable,
    input [7:0] counter_value,
    output reg timeout
);
    reg [7:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= counter_value;
            timeout <= 0;
        end else if (enable) begin
            if (counter > 0) begin
                counter <= counter - 1;
                timeout <= 0;
            end else begin
                timeout <= 1; // Trigger timeout
            end
        end
    end
endmodule

