module iir_filter(clk, reset, x_in, y_out);  
    input clk;  
    input reset;  
    input signed [15:0] x_in;  
    output signed [15:0] y_out;  

    reg signed [15:0] y;  
    reg signed [15:0] x [0:4];  
    reg signed [15:0] y_prev [0:4];  

    // Coefficients (example values)
    parameter signed [15:0] a0 = 16'h1;
    parameter signed [15:0] a1 = 16'h2;
    parameter signed [15:0] a2 = 16'h1;
    parameter signed [15:0] b1 = 16'h1;
    parameter signed [15:0] b2 = 16'h1;

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            y <= 0;  
            x[0] <= 0;  
            x[1] <= 0;  
            x[2] <= 0;  
            x[3] <= 0;  
            x[4] <= 0;  
            y_prev[0] <= 0;  
            y_prev[1] <= 0;  
            y_prev[2] <= 0;  
            y_prev[3] <= 0;  
            y_prev[4] <= 0;  
        end else begin  
            // Shift registers  
            x[4] <= x[3];  
            x[3] <= x[2];  
            x[2] <= x[1];  
            x[1] <= x[0];  
            x[0] <= x_in;  

            y_prev[4] <= y_prev[3];  
            y_prev[3] <= y_prev[2];  
            y_prev[2] <= y_prev[1];  
            y_prev[1] <= y_prev[0];  
            y_prev[0] <= y;  

            // IIR filter formula  
            y <= (a0 * x[0] + a1 * x[1] + a2 * x[2] - b1 * y_prev[1] - b2 * y_prev[2]) >>> 15;  
        end  
    end  

    assign y_out = y;  
endmodule

