module noise_suppression(
    input [4:0] in_signal,
    input clk,
    input reset,
    output reg [4:0] out_signal
);
    reg [4:0] prev_signal1;
    reg [4:0] prev_signal2;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            prev_signal1 <= 5'b0;
            prev_signal2 <= 5'b0;
            out_signal <= 5'b0;
        end else begin
            prev_signal2 <= prev_signal1;
            prev_signal1 <= in_signal;
            out_signal <= (prev_signal1 == prev_signal2) ? prev_signal1 : 5'b0;
        end
    end
endmodule

module pipeline_processor (
