module sd_card_controller(
    input clk,
    input reset,
    input start,
    input read_write, // 1 for read, 0 for write
    output reg [1:0] state // 0 for IDLE, 1 for READ, 2 for WRITE
);

    // State encoding
    parameter IDLE = 2'b00;
    parameter READ = 2'b01;
    parameter WRITE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        if (read_write) begin
                            state <= READ;
                        end else begin
                            state <= WRITE;
                        end
                    end
                end
                READ: begin
                    if (start) begin
                        state <= IDLE;
                    end
                end
                WRITE: begin
                    if (start) begin
                        state <= IDLE;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

