module divider_4bit(
    input clk,
    input start,
    input [3:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    output reg done
);
    reg [3:0] temp_dividend;
    reg [3:0] temp_quotient;
    reg [3:0] temp_remainder;
    reg [2:0] state;

    localparam IDLE = 3'b000,
               DIVIDE = 3'b001,
               DONE = 3'b010;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (start) begin
                    temp_dividend <= dividend;
                    temp_quotient <= 4'b0000;
                    temp_remainder <= 4'b0000;
                    state <= DIVIDE;
                    done <= 0;
                end
            end
            DIVIDE: begin
                if (temp_dividend >= divisor) begin
                    temp_dividend <= temp_dividend - divisor;
                    temp_quotient <= temp_quotient + 1;
                end else begin
                    temp_remainder <= temp_dividend;
                    quotient <= temp_quotient;
                    remainder <= temp_remainder;
                    state <= DONE;
                end
            end
            DONE: begin
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
endmodule

module butterworth_filter (
    input [4:0] x_in,
    output reg [4:0] y_out
);
    reg [4:0] a[0:4];  // Coefficients for the Butterworth filter
    reg [4:0] x[0:4];  // Input samples
    integer i;

    initial begin
        // Coefficients for a 4th order Butterworth filter (example values)
        a[0] = 5'b00001; // Example coefficient for x^0
        a[1] = 5'b00010; // Example coefficient for x^1
        a[2] = 5'b00100; // Example coefficient for x^2
        a[3] = 5'b01000; // Example coefficient for x^3
        a[4] = 5'b10000; // Example coefficient for x^4
    end

    always @(*) begin
        // Shift input samples
        x[4] = x[3];
        x[3] = x[2];
        x[2] = x[1];
        x[1] = x[0];
        x[0] = x_in;

        // Calculate the output using the filter coefficients
        y_out = (a[0] * x[0] + a[1] * x[1] + a[2] * x[2] + a[3] * x[3] + a[4] * x[4]) >> 2; // Right shift for scaling
    end
endmodule

module fir_filter (  
    input [3:0] x,  
    output [3:0] y  
);  
    // Coefficients for the FIR filter  
    reg [3:0] coeff [0:3];  
    initial begin  
        coeff[0] = 4'b0001;  
        coeff[1] = 4'b0010;  
        coeff[2] = 4'b0011;  
        coeff[3] = 4'b0100;  
    end  

    // Combinational logic for FIR filter  
    assign y = (coeff[0] * x) + (coeff[1] * x) + (coeff[2] * x) + (coeff[3] * x);  
endmodule

