module pwm_generator(
    input clk,
    input rst,
    input [7:0] duty_cycle, // Duty cycle in percentage (0-100)
    output reg pwm_out
);
    reg [7:0] counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 0;
            pwm_out <= 0;
        end else begin
            if (counter < 255) begin
                counter <= counter + 1;
            end else begin
                counter <= 0;
            end

            if (counter < (duty_cycle * 255) / 100) begin
                pwm_out <= 1;
            end else begin
                pwm_out <= 0;
            end
        end
    end
endmodule

