module merge_sort (
    input [31:0] arr_in, // 8 4-bit unsigned integers
    output reg [31:0] arr_out // sorted output
);
    integer i, j;
    reg [3:0] temp;

    always @(*) begin
        // Initialize output to input
        arr_out = arr_in;

        // Perform merge sort
        for (i = 0; i < 8; i = i + 1) begin
            for (j = i + 1; j < 8; j = j + 1) begin
                if (arr_out[4*i +: 4] > arr_out[4*j +: 4]) begin
                    // Swap
                    temp = arr_out[4*i +: 4];
                    arr_out[4*i +: 4] = arr_out[4*j +: 4];
                    arr_out[4*j +: 4] = temp;
                end
            end
        end
    end
endmodule

module pipelined_processor(clk, rst, instruction_in, data_in, result_out);  
    input clk;  
    input rst;  
    input [15:0] instruction_in;  
    input [15:0] data_in;  
    output reg [15:0] result_out;  

    reg [15:0] IF_ID_instruction;  
    reg [15:0] ID_EX_data1, ID_EX_data2;  
    reg [15:0] EX_MEM_result;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            IF_ID_instruction <= 0;  
            ID_EX_data1 <= 0;  
            ID_EX_data2 <= 0;  
            EX_MEM_result <= 0;  
            result_out <= 0;  
        end else begin  
            // Stage 1: Instruction Fetch  
            IF_ID_instruction <= instruction_in;  

            // Stage 2: Instruction Decode  
            ID_EX_data1 <= data_in;  // Assume data_in is the first operand  
            ID_EX_data2 <= data_in;  // Assume data_in is the second operand  

            // Stage 3: Execute  
            case (IF_ID_instruction[15:12]) // Opcode  
                4'b0000: EX_MEM_result <= ID_EX_data1 + ID_EX_data2; // ADD  
                4'b0001: EX_MEM_result <= ID_EX_data1 - ID_EX_data2; // SUB  
                4'b0010: EX_MEM_result <= ID_EX_data1 & ID_EX_data2; // AND  
                4'b0011: EX_MEM_result <= ID_EX_data1 | ID_EX_data2; // OR  
                default: EX_MEM_result <= 0;  
            endcase  

            // Stage 4: Memory Access (not implemented, assume direct write back)  
            // Stage 5: Write Back  
            result_out <= EX_MEM_result;  
        end  
    end  
endmodule

module voltage_regulator (  
    input [7:0] Vin,  
    input [7:0] Vtarget,  
    input [7:0] Vmin,  
    output reg [7:0] Vout  
);  
    always @(*) begin  
        if (Vin > Vtarget)  
            Vout = Vtarget;  
        else if (Vin < Vmin)  
            Vout = Vmin;  
        else  
            Vout = Vin;  
    end  
endmodule

module counter_16bit (
    input wire clk,
    input wire reset,
    output reg [15:0] count
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 16'b0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

