module DWT_Haar(input clk,  
                input rst,  
                input [7:0] data_in,  
                output reg [7:0] coeff_out);  

    reg [7:0] temp [0:7];  
    reg [2:0] count;  
    reg [7:0] low_pass;  
    reg [7:0] high_pass;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 0;  
            coeff_out <= 0;  
        end else begin  
            temp[count] <= data_in;  
            count <= count + 1;  

            if (count == 7) begin  
                // Perform the DWT  
                low_pass <= (temp[0] + temp[1]) >> 1;  
                high_pass <= (temp[0] - temp[1]) >> 1;  
                coeff_out <= {low_pass, high_pass,  
                              (temp[2] + temp[3]) >> 1, (temp[2] - temp[3]) >> 1,  
                              (temp[4] + temp[5]) >> 1, (temp[4] - temp[5]) >> 1,  
                              (temp[6] + temp[7]) >> 1, (temp[6] - temp[7]) >> 1};  
            end  
        end  
    end  
endmodule

