module state_machine (  
    input clk,  
    input rst,  
    input start,  
    output reg [1:0] state  
);  
    parameter IDLE = 2'b00, STATE1 = 2'b01, STATE2 = 2'b10;  
    always @(posedge clk or posedge rst) begin  
        if (rst)  
            state <= IDLE;  
        else begin  
            case (state)  
                IDLE: if (start) state <= STATE1;  
                STATE1: state <= STATE2;  
                STATE2: if (!start) state <= IDLE;  
            endcase  
        end  
    end  
endmodule

