module viterbi_decoder (
    input clk,
    input rst,
    input [1:0] encoded_bits,
    output reg [1:0] decoded_bits,
    output reg valid
);
    // state definitions
    parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
    reg [1:0] state, next_state;

    // state transition
    always @(posedge clk or posedge rst) begin
        if (rst)
            state <= S0;
        else
            state <= next_state;
    end

    // next state logic
    always @(*) begin
        case (state)
            S0: next_state = (encoded_bits == 2'b00) ? S0 : S1;
            S1: next_state = (encoded_bits == 2'b01) ? S2 : S3;
            S2: next_state = (encoded_bits == 2'b10) ? S0 : S1;
            S3: next_state = (encoded_bits == 2'b11) ? S2 : S3;
            default: next_state = S0;
        endcase
    end

    // output logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            decoded_bits <= 2'b00;
            valid <= 0;
        end else begin
            case (state)
                S0: begin
                    decoded_bits <= 2'b00; 
                    valid <= 1;
                end
                S1: begin
                    decoded_bits <= 2'b01; 
                    valid <= 1;
                end
                S2: begin
                    decoded_bits <= 2'b10; 
                    valid <= 1;
                end
                S3: begin
                    decoded_bits <= 2'b11; 
                    valid <= 1;
                end
                default: begin
                    decoded_bits <= 2'b00; 
                    valid <= 0;
                end
            endcase
        end
    end
endmodule

