module uart_transmitter (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire send,
    output reg tx,
    output reg busy
);

    reg [3:0] bit_count;
    reg [10:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit
    reg [15:0] baud_count; // Adjust for baud rate
    reg send_reg;

    // State machine states
    parameter IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;
    reg [1:0] state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            tx <= 1; // Idle state is high
            busy <= 0;
            bit_count <= 0;
            baud_count <= 0;
        end else begin
            state <= next_state;
        end
    end

    always @(state or send or bit_count) begin
        case (state)
            IDLE: begin
                if (send) begin
                    next_state = START;
                    busy = 1;
                    shift_reg = {1'b1, data_in, 1'b0}; // Prepare the shift register
                    bit_count = 0;
                end else begin
                    next_state = IDLE;
                end
            end
            START: begin
                next_state = DATA;
                tx = 0; // Start bit is low
            end
            DATA: begin
                if (bit_count < 8) begin
                    next_state = DATA;
                    tx = shift_reg[bit_count]; // Transmit data bits
                    bit_count = bit_count + 1;
                end else begin
                    next_state = STOP;
                end
            end
            STOP: begin
                next_state = IDLE;
                tx = 1; // Stop bit is high
                busy = 0;
            end
        endcase
    end
endmodule

