module adaptive_lms (
    input clk,
    input rst,
    input signed [15:0] x,     // input signal
    input signed [15:0] d,     // desired signal
    output reg signed [15:0] y, // output signal
    output reg signed [15:0] e  // error signal
);
    parameter N = 4; // Number of taps
    parameter mu = 16'h0001; // Step size

    reg signed [15:0] w [0:N-1]; // Weights
    reg signed [15:0] x_delay [0:N-1]; // Delay line

    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset weights and delay line
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= 16'h0000;
                x_delay[i] <= 16'h0000;
            end
            y <= 16'h0000;
            e <= 16'h0000;
        end else begin
            // Shift the input samples
            for (i = N-1; i > 0; i = i - 1) begin
                x_delay[i] <= x_delay[i-1];
            end
            x_delay[0] <= x;

            // Calculate output
            y <= 0;
            for (i = 0; i < N; i = i + 1) begin
                y <= y + (w[i] * x_delay[i]);
            end

            // Calculate error
            e <= d - y;

            // Update weights
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= w[i] + (mu * e * x_delay[i]);
            end
        end
    end
endmodule

