module deserializer(  
    input clk,  
    input rst,  
    input [15:0] serialized_in,  
    output reg [15:0] parallel_out  
);  
    integer i;  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            parallel_out <= 16'b0;  
            i <= 0;  
        end  
        else if (i < 16) begin  
            parallel_out[i] <= serialized_in[i];  
            i <= i + 1;  
        end  
    end  
endmodule

