module switching_regulator(  
    input clk,  
    input rst,  
    input [7:0] vout, // Output voltage sensor input  
    input [7:0] vref, // Reference voltage input  
    output reg pwm_out // PWM output signal  
);  
    reg [15:0] integral;  
    reg [7:0] error;  
    reg [15:0] kp = 16; // Proportional gain  
    reg [15:0] ki = 1;  // Integral gain  
    reg [15:0] pwm_value;  
    parameter MAX_PWM = 255; // Maximum PWM value  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            integral <= 0;  
            pwm_value <= 0;  
            pwm_out <= 0;  
        end else begin  
            error <= vref - vout;  
            integral <= integral + error;  
            pwm_value <= (kp * error + ki * integral) >> 8;  
            if (pwm_value > MAX_PWM)  
                pwm_value <= MAX_PWM;  
            pwm_out <= (pwm_value > 128) ? 1 : 0; // Example PWM signal generation  
        end  
    end  
endmodule
